{{ config(
            materialized='table',
                post_hook={
                    "sql": "Create or replace table snitch_db.maplemonk.LIQUIDATION_growth_list as Select * from ( With Consol as ( SELECT * from ( Select *, CASE WHEN POSITION(\'-\' IN SKU) > 0 AND LEFT(SKU, 2) = \'SH\' THEN SPLIT_PART(SKU, \'-\', 1) WHEN POSITION(\'-\' IN SKU) > 0 THEN SPLIT_PART(SKU, \'-\', 1) || \'-\' || SPLIT_PART(SKU, \'-\', 2) ELSE SKU END AS extracted_value , REVERSE(SUBSTRING(REVERSE(CASE WHEN POSITION(\'-\' IN SKU) > 0 AND LEFT(SKU, 2) = \'SH\' THEN SPLIT_PART(SKU, \'-\', 1) WHEN POSITION(\'-\' IN SKU) > 0 THEN SPLIT_PART(SKU, \'-\', 1) || \'-\' || SPLIT_PART(SKU, \'-\', 2) ELSE SKU END), CHARINDEX(\'-\', REVERSE(CASE WHEN POSITION(\'-\' IN SKU) > 0 AND LEFT(SKU, 2) = \'SH\' THEN SPLIT_PART(SKU, \'-\', 1) WHEN POSITION(\'-\' IN SKU) > 0 THEN SPLIT_PART(SKU, \'-\', 1) || \'-\' || SPLIT_PART(SKU, \'-\', 2) ELSE SKU END)) + 1)) AS sku_group from ( Select *, case when UNITS_ON_HAND >5 then \'Growth\' else \'Liquidate\' end as status from ( SELECT inv.\"Item SkuCode\" AS sku, SUM( COALESCE(TRY_CAST(CAST(inv.inventory AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Bad Inventory\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Inventory Blocked\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Not Found\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Putaway Pending\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Putback Pending\" AS STRING) AS FLOAT), 0) ) AS units_on_hand, COALESCE(SUM(sales.qty), 0) AS last_30d_qty FROM snitch_db.maplemonk.snitch_final_inventory_wh2 inv LEFT JOIN ( SELECT sku, SUM(suborder_quantity) AS qty FROM snitch_db.maplemonk.unicommerce_fact_items_snitch WHERE marketplace_mapped NOT IN (\'OWN_STORE\',\'CUSTOM\',\'Own Store\',\'FRANCHISE_STORE\',\'Franchise Store\') AND order_date >= CURRENT_DATE - 30 AND shippingpackagestatus IS NOT NULL GROUP BY sku ) sales ON inv.\"Item SkuCode\" = sales.sku WHERE inv.date = CURRENT_DATE AND CAST(inv.facility AS VARCHAR) IN (\'SAPL-WH2\', \'SAPL_EMIZA\', \'SAPL-WH1\') GROUP BY inv.\"Item SkuCode\" HAVING SUM( COALESCE(TRY_CAST(CAST(inv.inventory AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Bad Inventory\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Inventory Blocked\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Not Found\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Putaway Pending\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Putback Pending\" AS STRING) AS FLOAT), 0) ) > 0 ) where LAST_30D_QTY =0 ) ) ), class as ( Select * from ( Select * , ROW_NUMBER() OVER (PARTITION BY sku_group ORDER BY 1) AS rn from snitch_db.maplemonk.availability_master_v2) where rn =1) Select a.*, b.sku_class, b.category from consol a left join class b on a.EXTRACTED_VALUE = b.sku_group ) where sku_class !=\'Not-Cataloged\'; ----- Create or replace table snitch_db.maplemonk.doi_list as Select * , CASE WHEN DOI =0 THEN \'No Sales\' WHEN DOI > 0 and DOI < 30 THEN \'0-30\' WHEN DOI >= 30 AND DOI < 60 THEN \'30-60\' WHEN DOI >= 60 AND DOI < 90 THEN \'60-90\' WHEN DOI >= 90 AND DOI < 120 THEN \'90-120\' WHEN DOI >= 120 AND DOI < 150 THEN \'120-150\' WHEN DOI >= 150 AND DOI < 180 THEN \'150-180\' WHEN DOI >= 180 AND DOI < 210 THEN \'180-210\' WHEN DOI >= 210 AND DOI < 240 THEN \'210-240\' WHEN DOI >= 240 AND DOI < 270 THEN \'240-270\' WHEN DOI >= 270 AND DOI < 300 THEN \'270-300\' WHEN DOI >= 300 AND DOI < 330 THEN \'300-330\' WHEN DOI >= 330 AND DOI < 360 THEN \'330-360\' WHEN DOI >= 360 AND DOI < 720 THEN \'360-720\' WHEN DOI >= 720 AND DOI < 1000 THEN \'720-1000\' ELSE \'> 1000\' END AS DOI_Interals, from ( Select *, case when LAST_30D_QTY = 0 then 0 else div0(UNITS_ON_HAND,LAST_30D_QTY)*90 END as DOI from ( With Consol as ( SELECT * from ( Select *, CASE WHEN POSITION(\'-\' IN SKU) > 0 AND LEFT(SKU, 2) = \'SH\' THEN SPLIT_PART(SKU, \'-\', 1) -- For SKUs starting with \'SH\' (e.g., SH0015-40 -> SH0015) WHEN POSITION(\'-\' IN SKU) > 0 THEN SPLIT_PART(SKU, \'-\', 1) || \'-\' || SPLIT_PART(SKU, \'-\', 2) -- For other SKUs with \'-\' ELSE SKU -- For SKUs without \'-\' END AS extracted_value , REVERSE(SUBSTRING(REVERSE(CASE WHEN POSITION(\'-\' IN SKU) > 0 AND LEFT(SKU, 2) = \'SH\' THEN SPLIT_PART(SKU, \'-\', 1) -- For SKUs starting with \'SH\' (e.g., SH0015-40 -> SH0015) WHEN POSITION(\'-\' IN SKU) > 0 THEN SPLIT_PART(SKU, \'-\', 1) || \'-\' || SPLIT_PART(SKU, \'-\', 2) -- For other SKUs with \'-\' ELSE SKU -- For SKUs without \'-\' END), CHARINDEX(\'-\', REVERSE(CASE WHEN POSITION(\'-\' IN SKU) > 0 AND LEFT(SKU, 2) = \'SH\' THEN SPLIT_PART(SKU, \'-\', 1) -- For SKUs starting with \'SH\' (e.g., SH0015-40 -> SH0015) WHEN POSITION(\'-\' IN SKU) > 0 THEN SPLIT_PART(SKU, \'-\', 1) || \'-\' || SPLIT_PART(SKU, \'-\', 2) -- For other SKUs with \'-\' ELSE SKU -- For SKUs without \'-\' END)) + 1)) AS sku_group from ( Select *, case when UNITS_ON_HAND >5 then \'Growth\' else \'Liquidate\' end as status from ( SELECT inv.\"Item SkuCode\" AS sku, SUM( COALESCE(TRY_CAST(CAST(inv.inventory AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Bad Inventory\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Inventory Blocked\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Not Found\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Putaway Pending\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Putback Pending\" AS STRING) AS FLOAT), 0) ) AS units_on_hand, COALESCE(SUM(sales.qty), 0) AS last_30d_qty FROM snitch_db.maplemonk.snitch_final_inventory_wh2 inv LEFT JOIN ( SELECT sku, SUM(suborder_quantity) AS qty FROM snitch_db.maplemonk.unicommerce_fact_items_snitch WHERE marketplace_mapped NOT IN (\'OWN_STORE\',\'CUSTOM\',\'Own Store\',\'FRANCHISE_STORE\',\'Franchise Store\') AND order_date >= CURRENT_DATE - 90 AND shippingpackagestatus IS NOT NULL GROUP BY sku ) sales ON inv.\"Item SkuCode\" = sales.sku WHERE inv.date = CURRENT_DATE AND CAST(inv.facility AS VARCHAR) IN (\'SAPL-WH2\', \'SAPL_EMIZA\', \'SAPL-WH1\') GROUP BY inv.\"Item SkuCode\" HAVING SUM( COALESCE(TRY_CAST(CAST(inv.inventory AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Bad Inventory\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Inventory Blocked\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Not Found\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Putaway Pending\" AS STRING) AS FLOAT), 0) + COALESCE(TRY_CAST(CAST(inv.\"Putback Pending\" AS STRING) AS FLOAT), 0) ) > 0 ) ) ) ), class as ( Select * from ( Select * , ROW_NUMBER() OVER (PARTITION BY sku_group ORDER BY 1) AS rn from snitch_db.maplemonk.availability_master_v2) where rn =1) Select a.*, b.sku_class, b.category from consol a left join class b on a.EXTRACTED_VALUE = b.sku_group ) )",
